using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// A sample type whose metadata will be generated via source-gen
public record WeatherForecast(DateTime Date, int TemperatureC, string? Summary);

// Source-generated context (only WeatherForecast is included)
[JsonSerializable(typeof(WeatherForecast))]
public partial class AppJsonContext : JsonSerializerContext { }

var options = new JsonSerializerOptions();
options.TypeInfoResolverChain.Add(AppJsonContext.Default);

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T>
JsonTypeInfo<WeatherForecast> typedInfo = (JsonTypeInfo<WeatherForecast>)options.GetTypeInfo(typeof(WeatherForecast));
Console.WriteLine($"Got typed metadata for: {typedInfo.Type.Name}");

// 2) Probe without throwing: TryGetTypeInfo returns false if not available
bool found = options.TryGetTypeInfo(typeof(WeatherForecast), out JsonTypeInfo? info1);
Console.WriteLine($"WeatherForecast available? {found} -> {info1?.Type.Name}");

bool notFound = options.TryGetTypeInfo(typeof(int), out JsonTypeInfo? info2);
Console.WriteLine($"int available? {notFound} -> {(info2 is null ? "(null)" : info2.Type.Name)}");
EOF
